<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { agregarPaso, crearTipo, detalleTipo, eliminarPaso, listarTipos } from '../services/tiposAtencion'
import type { Accion, TipoAtencion } from '../interfaces/tiposAtencion.interface'
const rows=ref<TipoAtencion[]>([]),acciones=ref<Accion[]>([]),detail=ref<TipoAtencion|null>(null),modal=ref<'nuevo'|'paso'|null>(null),criterio=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref('')
const form=reactive({tipo:'',nombre:''}),paso=reactive({accion_id:'',condicion:'',tipo_accion:'',secuencia:''})
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
async function load(p=1){page.value=p;loading.value=true;error.value='';try{const r=await listarTipos(criterio.value,p);rows.value=r.data;acciones.value=r.acciones;total.value=r.total;lastPage.value=r.last_page}catch(e){error.value=message(e)}finally{loading.value=false}}
async function show(x:TipoAtencion){try{detail.value=await detalleTipo(x.id)}catch(e){error.value=message(e)}}function openNew(){Object.assign(form,{tipo:'',nombre:''});modal.value='nuevo'}function openStep(){Object.assign(paso,{accion_id:'',condicion:'',tipo_accion:'',secuencia:''});modal.value='paso'}
async function submit(){saving.value=true;error.value='';try{if(modal.value==='nuevo'){if(form.nombre.trim().length<2)throw new Error('Ingrese una descripción válida.');await crearTipo(form)}else if(detail.value){await agregarPaso(detail.value.id,{...paso})}success.value='Información guardada correctamente.';modal.value=null;if(detail.value)detail.value=await detalleTipo(detail.value.id);await load(page.value)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function remove(x:number){if(!detail.value||!confirm('¿Retirar esta acción del flujo?'))return;try{await eliminarPaso(detail.value.id,x);detail.value=await detalleTipo(detail.value.id);success.value='Acción retirada del flujo.'}catch(e){error.value=message(e)}}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Comercialización / Tipos de atención</nav><header class="hero"><div class="mark">FA</div><div><small>EVAN · CONFIGURACIÓN COMERCIAL</small><h1>Tipos de atención</h1><p>Catálogo de solicitudes, reclamos y sus flujos de procedimiento.</p></div><strong>{{total}} tipos</strong><button @click="openNew">+ Agregar tipo</button></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="search"><input v-model.trim="criterio" placeholder="Buscar tipo de atención" @keyup.enter="load(1)"><button @click="load(1)">Buscar</button></section><div v-if="loading" class="empty">Cargando tipos de atención…</div><div v-else-if="!rows.length" class="empty">No se encontraron registros.</div><section v-else class="cards"><article v-for="x in rows" :key="x.id"><header><span>{{x.tipo}}</span><small>#{{x.id}}</small></header><h2>{{x.nombre}}</h2><p>{{x.grupo||'Flujo comercial'}} · {{x.pasos?.length||0}} acciones configuradas</p><button @click="show(x)">Establecer flujo</button></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="detail&&!modal" class="backdrop" @mousedown.self="detail=null"><section class="flow"><header><div><small>FLUJO DE PROCEDIMIENTO</small><h2>{{detail.nombre}}</h2><p>{{detail.pasos?.length||0}} acciones establecidas</p></div><button @click="detail=null">×</button></header><div class="flowbar"><b>Secuencia configurada</b><button @click="openStep">+ Añadir acción</button></div><div v-if="!detail.pasos?.length" class="empty">Aún no se han establecido acciones.</div><ol v-else><li v-for="x in detail.pasos" :key="x.pivot_id||x.id"><i>{{x.secuencia}}</i><div><b>{{x.nombre}}</b><p>{{x.descripcion||'Sin descripción adicional.'}}</p><small>{{x.seccion}} · Condición {{x.condicion||'—'}} · {{x.tipo_accion===1?'Acción Sí':'Acción No'}}</small></div><button @click="remove(x.id)">Retirar</button></li></ol><footer><button @click="detail=null">Cerrar</button></footer></section></div>
<div v-if="modal" class="backdrop" @mousedown.self="modal=null"><form class="modal" @submit.prevent="submit"><header><div><small>CONFIGURACIÓN COMERCIAL</small><h2>{{modal==='nuevo'?'Nuevo tipo de atención':'Agregar acción al flujo'}}</h2></div><button type="button" @click="modal=null">×</button></header><template v-if="modal==='nuevo'"><label>Tipo de flujo *<select v-model="form.tipo" required><option value="">Seleccione</option><option value="R">Reclamo</option><option value="S">Solicitud</option><option value="SF">Solicitud de factibilidad</option><option value="SM">Contrastación de medidor</option><option value="SC">Cambio de nombre</option></select></label><label>Descripción *<input v-model.trim="form.nombre" maxlength="255" required></label></template><template v-else><label>Acción *<select v-model="paso.accion_id" required><option value="">Seleccione</option><option v-for="x in acciones" :key="x.id" :value="x.id">{{x.nombre}} ({{x.seccion}})</option></select></label><div class="grid"><label>Condición *<select v-model="paso.condicion" required><option value="">Seleccione</option><option>SI</option><option>NO</option></select></label><label>Tipo de acción *<select v-model="paso.tipo_accion" required><option value="">Seleccione</option><option value="1">Acción Sí</option><option value="0">Acción No</option></select></label><label>Secuencia *<select v-model="paso.secuencia" required><option value="">Seleccione</option><option v-for="x in 8" :key="x">{{x}}</option></select></label></div></template><footer><button type="button" class="clear" @click="modal=null">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar'}}</button></footer></form></div></div></template>
<style scoped>
.page{--a:#1689a5;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:700}.hero small,.modal small,.flow small{color:var(--a);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7d898f;font-size:.65rem}.hero strong{margin-left:auto;font-size:.58rem}.hero button,.search button,.pages button,.modal footer button,.flowbar button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.56rem}.flash{padding:10px;font-size:.63rem}.flash.good{color:#287258;background:#edf9f3}.flash.error{color:#a13f43;background:#fff0f0}.search{margin-top:13px;padding:12px;display:flex;background:#fff}.search input{flex:1}input,select{width:100%;padding:9px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.58rem}.cards{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{padding:15px;border-top:3px solid var(--a);border-radius:9px;background:#fff}.cards article header{display:flex;justify-content:space-between}.cards article header span{padding:4px 7px;border-radius:9px;color:var(--a);background:#eaf8f8;font-size:.48rem}.cards h2{min-height:35px;font-size:.65rem}.cards p{color:#7d898f;font-size:.51rem}.cards article>button{width:100%;padding:8px;border:0;border-radius:5px;color:#fff;background:var(--a);font-size:.52rem}.empty{padding:45px;text-align:center;background:#fff;font-size:.6rem}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal,.flow{width:min(100%,700px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.flow{width:min(100%,850px)}.modal>header,.flow>header{display:flex}.modal h2,.flow h2{margin:2px 0;font-size:1rem}.modal>header>button,.flow>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin:12px 0;font-size:.55rem}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.modal footer,.flow footer{margin-top:15px;display:flex;justify-content:flex-end;gap:6px}.clear,.flow footer button{padding:8px 11px;border:0;border-radius:6px;color:#68757c!important;background:#edf1f3!important}.flowbar{margin-top:14px;padding:10px;display:flex;align-items:center;justify-content:space-between;background:#f5f8f9;font-size:.56rem}.flow ol{padding:0;list-style:none}.flow li{padding:12px 5px;display:flex;align-items:center;gap:10px;border-bottom:1px solid #e9edef}.flow li i{width:27px;height:27px;display:grid;place-items:center;border-radius:50%;color:#fff;background:var(--a);font-size:.52rem;font-style:normal}.flow li div{flex:1}.flow li b,.flow li p,.flow li small{display:block;margin:2px 0;font-size:.53rem}.flow li p{color:#68767c}.flow li button{border:0;color:#b14a50;background:none;font-size:.49rem}@media(max-width:760px){.cards{grid-template-columns:1fr 1fr}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}@media(max-width:500px){.cards,.grid{grid-template-columns:1fr}}
</style>
